syntax:
ReturnType operator<operator symbol>(const ClassName& other) {
    // implementation
}

code_example:
#include <iostream>
class Vector2D {
public:
    double x, y;
    Vector2D(double x, double y) : x(x), y(y) {}
    // Overload the + operator to add two Vector2D objects
    Vector2D operator+(const Vector2D& other) const {
        return Vector2D(x + other.x, y + other.y);
    }
    void print() const { std::cout << "(" << x << ", " << y << ")"; }
};
int main() {
    Vector2D v1(1.0, 2.0);
    Vector2D v2(3.0, 4.0);
    Vector2D v3 = v1 + v2; // Uses overloaded + operator
    v3.print(); // Output: (4.0, 6.0)
    return 0;
}
